import React, { useState } from 'react';
import { useCSideBar } from '@cloud-materials/common';
import type { MenuItemConfig } from '../interface';

type StateType = ReturnType<typeof useCSideBar>[0];
type ControlType = ReturnType<typeof useCSideBar>[1];

const renderMenu = (menus: StateType['menus'], sidebarState: StateType, control: ControlType, level = 0) => {
  const { openKeys, selectedKeys } = sidebarState;
  const indent = level * 12 + 2;
  return menus?.map(menu => {
    if (menu.type === 'sub-menu') {
      return (
        <details
          open={openKeys.includes(menu.key)}
          key={menu.key}
          style={{
            paddingLeft: indent,
          }}
        >
          <summary
            onClick={e => {
              e.preventDefault();
              control.setOpenKeys(menu.key);
            }}
            style={{ padding: '10px 0', cursor: 'pointer' }}
          >
            {menu.icon}&nbsp;{menu.title}
          </summary>
          {renderMenu(menu.children, sidebarState, control, level + 1)}
        </details>
      );
    }

    if (!menu.type || menu.type === 'menu') {
      return (
        <p
          key={menu.key}
          style={{
            cursor: 'pointer',
            paddingLeft: indent,
            background: selectedKeys.includes(menu.key) ? '#fff' : '',
          }}
          onClick={() => {
            control.onClickMenuItem(menu.key);
          }}
        >
          {menu.label}
        </p>
      );
    }

    return <p key={menu.key}>未实现</p>;
  });
};

