import { CSideBar, IconApps, IconFindReplace, IconHome, Input } from '@cloud-materials/common';
import { useDebounceFn } from 'ahooks';
import React, { useMemo, useState } from 'react';
import type { MenuItemConfig } from '../interface';

export default () => {
  const [search, setSearch] = useState('');

  const { run } = useDebounceFn((value: string) => {
    setSearch(value);
  });

  const menus = useMemo(() => {
    const initialMenus: MenuItemConfig[] = [
      { label: '概览', key: '1', icon: <IconHome /> },
      {
        type: 'custom',
        key: 'custom',
        render() {
          return <Input.Search placeholder="输入内容以搜索菜单" style={{ marginBottom: 4 }} onChange={run} />;
        },
      },
      {
        title: '镜像管理',
        key: 'image',
        type: 'sub-menu',
        icon: <IconApps />,
        children: [
          {
            label: '镜像列表',
            key: 'image-1',
          },
          {
            label: '镜像创建',
            key: 'image-2',
          },
          {
            label: '镜像删除',
            key: 'image-3',
          },
        ],
      },
      {
        title: '集群管理',
        key: 'cluster',
        type: 'sub-menu',
        icon: <IconFindReplace />,
        children: [
          {
            label: '集群列表',
            key: 'cluster-1',
          },
          {
            label: '集群创建',
            key: 'cluster-2',
          },
          {
            label: '集群删除',
            key: 'cluster-3',
          },
        ],
      },
    ];

    const highlightName = (title: string) => {
      const splitStr = title.split(search);
      if (splitStr.length > 1) {
        return splitStr
          .map((string, index) => {
            if (index < splitStr.length - 1) {
              return [
                string,
                <span style={{ color: 'red' }} key={index}>
                  {search}
                </span>,
              ];
            }
            return string;
          })
          .flat();
      }
      return title;
    };

    if (search) {
      const recursionMenus = (menus: MenuItemConfig[]): MenuItemConfig[] => {
        return menus.map(menu => {
          if (menu.type === 'sub-menu') {
            return {
              ...menu,
              title: typeof menu.title === 'string' && highlightName(menu.title),
              children: menu.children && recursionMenus(menu.children),
            };
          }

          if (!menu.type || menu.type === 'menu') {
            return {
              ...menu,
              label: typeof menu.label === 'string' && highlightName(menu.label),
            };
          }

          return menu;
        });
      };

      return recursionMenus(initialMenus);
    }

    return initialMenus;
  }, [search]);

  return <CSideBar title={{ text: '对菜单进行搜索' }} menus={menus} style={{ height: 600 }} defaultOpenSubMenu />;
};

